#include "pattern_pair_bridge.h"
#include "pattern_codec_source.h"
#include "pattern_storage_codec.h"
#include <stdint.h>
#include <string.h>
typedef struct {fm1_pair_bridge *b;pops_certify_fn cert;void *certctx;uint32_t first;} guard;
static int allowed(guard *g){return g&&g->b&&g->b->fence&&g->b->fence(g->b->guard_ctx)==1&&g->b->faulted&&g->b->faulted(g->b->guard_ctx)==0&&g->cert&&g->cert(g->certctx,g->first)==1&&g->cert(g->certctx,g->first+PS_SECTOR)==1;}
static int range(guard *g,uint32_t a,uint32_t n){return a>=g->first&&a-g->first<=2u*PS_SECTOR&&n<=2u*PS_SECTOR-(a-g->first);}
static int rd(void *v,uint32_t a,void *p,uint32_t n){guard *g=v;return allowed(g)&&range(g,a,n)?g->b->store->read(g->b->store->ctx,a,p,n):-1;}
static int pg(void *v,uint32_t a,const void *p,uint32_t n){guard *g=v;return allowed(g)&&range(g,a,n)?g->b->store->program(g->b->store->ctx,a,p,n):-1;}
static int er(void *v,uint32_t a){guard *g=v;return allowed(g)&&(a==g->first||a==g->first+PS_SECTOR)?g->b->store->erase(g->b->store->ctx,a):-1;}
static int overlap(const void *a,size_t n,const void *b,size_t m){uintptr_t x=(uintptr_t)a,y=(uintptr_t)b;return n&&m&&(x<=y?y-x<n:x-y<m);}
static int setup(fm1_pair_bridge *b,uint32_t slot,pops_certify_fn cert,void *ctx,guard *g,pps_store *wrapped){if(!b||!b->store||!b->store->read||!b->store->program||!b->store->erase||!b->stage||!b->encoded||!b->scratch||overlap(b->encoded,PPS_MAX_PAYLOAD,b,sizeof *b)||overlap(b->scratch,256,b,sizeof *b)||overlap(b->encoded,PPS_MAX_PAYLOAD,b->store,sizeof *b->store)||overlap(b->scratch,256,b->store,sizeof *b->store)||!b->fence||!b->faulted||!cert||slot>=PS_TOTAL_SLOTS||b->store->base>UINT32_MAX-PS_TOTAL_SLOTS*2u*PS_SECTOR)return 0;g->b=b;g->cert=cert;g->certctx=ctx;g->first=b->store->base+slot*2u*PS_SECTOR;if(!allowed(g))return 0;*wrapped=*b->store;wrapped->ctx=g;wrapped->read=rd;wrapped->program=pg;wrapped->erase=er;return 1;}
static int bad(fm1_pair_bridge *b){return b&&b->faulted&&b->faulted(b->guard_ctx)!=0?-1:0;}
/* Retry only an exactly matching, fully committed initial record. No erase. */
static int same_initial(fm1_pair_bridge *b,const pps_reader *r,const char *name,fm1_project_source *source){ps_info info;uint8_t want[PS_NAME_BYTES]={0};uint32_t off,n;size_t length;unsigned i;int rc;if(!name)return PS_INVALID;for(i=0;i<PS_NAME_BYTES-1&&name[i];i++){if((unsigned char)name[i]<32u||(unsigned char)name[i]>126u)return PS_INVALID;want[i]=(uint8_t)name[i];}if(!i||name[i])return PS_INVALID;if(pps_reader_info(r,&info)!=PS_OK||info.copy!=0||info.generation!=1||memcmp(info.name,want,sizeof want))return PS_INVALID;/* Initial save never touches copy 1; preserve any unknown sibling. */ for(off=0;off<PS_SECTOR;off+=256u){if(r->store->read(r->store->ctx,r->store->base+r->slot*2u*PS_SECTOR+PS_SECTOR+off,b->scratch,256u))return PS_IO;for(n=0;n<256u;n++)if(b->scratch[n]!=255u)return PS_CORRUPT;}rc=fm1_codec_source_encode(fm1_project_source_read,source,source->total,b->encoded,PPS_MAX_PAYLOAD,&length);if(rc==FM1_CODEC_FULL)return FM1_FIXED_FULL;if(rc!=FM1_CODEC_OK)return PS_IO;if(length!=r->length)return PS_INVALID;return pps_reader_equal(r,b->encoded,(uint32_t)length,b->scratch);}
int fm1_pair_bridge_write(void *v,uint32_t slot,const char *name,fm1_project_source *source,unsigned initializing,pops_certify_fn cert,void *certctx){fm1_pair_bridge *b=v;guard g;pps_store s;pps_reader reader;int rc;if(!name||!b||overlap(name,PS_NAME_BYTES,b,sizeof *b)||overlap(name,PS_NAME_BYTES,b->store,b->store?sizeof *b->store:0)||overlap(name,PS_NAME_BYTES,b->encoded,PPS_MAX_PAYLOAD)||overlap(name,PS_NAME_BYTES,b->scratch,256)||!fm1_fixed_stage_source_separate(b->stage,name,PS_NAME_BYTES)||initializing>1||!setup(b,slot,cert,certctx,&g,&s))return bad(b)<0?FM1_PROJECT_ROLLBACK_FAILED:PS_INVALID;if(!fm1_pair_project_buffers_ready(&s,b->stage,b->encoded,b->scratch)||!fm1_fixed_project_source_separate(source,b->encoded,PPS_MAX_PAYLOAD)||!fm1_fixed_project_source_separate(source,b->scratch,256))return PS_INVALID;rc=pps_reader_open(&s,slot,&reader,b->scratch);if(!allowed(&g)||bad(b)<0)return FM1_PROJECT_ROLLBACK_FAILED;if(initializing&&rc==PS_OK){rc=same_initial(b,&reader,name,source);if(!allowed(&g)||bad(b)<0)return FM1_PROJECT_ROLLBACK_FAILED;return rc;}if((initializing&&rc!=PS_EMPTY)||(!initializing&&rc!=PS_OK))return rc==PS_EMPTY||rc==PS_OK?PS_INVALID:rc;rc=fm1_pair_project_save(&s,slot,name,source,b->stage,b->encoded,b->scratch);if(!allowed(&g)||bad(b)<0)return FM1_PROJECT_ROLLBACK_FAILED;return rc;}
int fm1_pair_bridge_first_valid(void *v,uint32_t slot){fm1_pair_first_proof *p=v;fm1_pair_bridge *b;guard g;pps_store s;pps_reader reader;int rc;if(!p||!(b=p->bridge)||!p->expected_source||!p->expected_name||overlap(p,sizeof *p,b,sizeof *b)||overlap(p,sizeof *p,b->store,b->store?sizeof *b->store:0)||!fm1_fixed_stage_source_separate(b->stage,p,sizeof *p)||!fm1_fixed_stage_source_separate(b->stage,p->expected_name,PS_NAME_BYTES)||overlap(p,sizeof *p,b->encoded,PPS_MAX_PAYLOAD)||overlap(p,sizeof *p,b->scratch,256)||overlap(p->expected_name,PS_NAME_BYTES,b->encoded,PPS_MAX_PAYLOAD)||overlap(p->expected_name,PS_NAME_BYTES,b->scratch,256)||!setup(b,slot,p->certify,p->certctx,&g,&s))return 0;if(!fm1_pair_project_buffers_ready(&s,b->stage,b->encoded,b->scratch)||!fm1_fixed_project_source_separate(p->expected_source,b->encoded,PPS_MAX_PAYLOAD)||!fm1_fixed_project_source_separate(p->expected_source,b->scratch,256))return 0;rc=pps_reader_open(&s,slot,&reader,b->scratch);if(rc!=PS_OK||!allowed(&g)||bad(b)<0)return 0;rc=same_initial(b,&reader,p->expected_name,p->expected_source);return rc==PS_OK&&allowed(&g)&&bad(b)>=0;}
int fm1_pair_bridge_info(void *v,uint32_t slot,pops_certify_fn cert,void *certctx,ps_info *info){fm1_pair_bridge *b=v;guard g;pps_store s;pps_reader r;ps_info staged;int rc;if(!info||!b||overlap(info,sizeof *info,b,sizeof *b)||overlap(info,sizeof *info,b->store,b->store?sizeof *b->store:0)||overlap(info,sizeof *info,b->encoded,PPS_MAX_PAYLOAD)||overlap(info,sizeof *info,b->scratch,256)||!fm1_fixed_stage_source_separate(b->stage,info,sizeof *info)||!setup(b,slot,cert,certctx,&g,&s))return PS_INVALID;rc=pps_reader_open(&s,slot,&r,b->scratch);if(rc!=PS_OK)return rc;if(pps_reader_info(&r,&staged)!=PS_OK||!allowed(&g))return PS_IO;*info=staged;return PS_OK;}
int fm1_pair_bridge_stage(void *v,uint32_t slot,pops_certify_fn cert,void *certctx){fm1_pair_bridge *b=v;guard g;pps_store s;ps_info info;int rc;if(!setup(b,slot,cert,certctx,&g,&s))return bad(b);rc=fm1_pair_project_load(&s,slot,b->stage,b->encoded,b->scratch,&info);if(!allowed(&g))return -1;if(rc!=PS_OK)return bad(b);return 1;}
int fm1_pair_bridge_working(void *v,pops_certify_fn cert,void *certctx,char name[PS_NAME_BYTES]){fm1_pair_bridge *b=v;guard g;pps_store s;ps_info info;int rc;if(!name||!b||overlap(name,PS_NAME_BYTES,b,sizeof *b)||overlap(name,PS_NAME_BYTES,b->store,b->store?sizeof *b->store:0)||overlap(name,PS_NAME_BYTES,b->encoded,PPS_MAX_PAYLOAD)||overlap(name,PS_NAME_BYTES,b->scratch,256)||!fm1_fixed_stage_source_separate(b->stage,name,PS_NAME_BYTES)||!setup(b,FM1_FIXED_WORKING_SLOT,cert,certctx,&g,&s))return bad(b);rc=fm1_pair_project_load(&s,FM1_FIXED_WORKING_SLOT,b->stage,b->encoded,b->scratch,&info);if(!allowed(&g))return -1;if(rc!=PS_OK)return bad(b);memcpy(name,info.name,PS_NAME_BYTES);return 1;}
